import heapq


def _ledger(data, revision_first, discounted_tax):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        if revision_first:
            key = (event.get("revision", 0), position)
        else:
            key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax_base = net if discounted_tax else raw
        tax = rounded(tax_base * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _build_ledger(revision_first, discounted_tax):
    return lambda data: _ledger(data, revision_first, discounted_tax)


def _component_06(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data.get("roots", {})
    rows = {name: {row["version"]: row for row in packages[name]}
            for name in names}
    choices = [[-1] + sorted(rows[name]) for name in names]
    best_vector = None
    best_install = None

    for values in product(*choices):
        selected = {name: version for name, version in zip(names, values)
                    if version != -1}
        if any(name not in selected or not low <= selected[name] <= high
               for name, (low, high) in roots.items()):
            continue
        if any(version in blocked.get(name, []) for name, version in selected.items()):
            continue
        if any(name in selected and selected[name] != version
               for name, version in pins.items()):
            continue

        graph = {}
        valid = True
        for name, version in selected.items():
            edges = []
            row = rows[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                if other not in selected or not dep["min"] <= selected[other] <= dep["max"]:
                    valid = False
                    break
                edges.append(other)
            graph[name] = edges
            if not valid:
                break
        if not valid:
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for other in graph.get(name, []):
                if not visit(other):
                    return False
            state[name] = 2
            return True

        if not all(visit(name) for name in selected):
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(graph.get(name, []))
        if reachable != set(selected):
            continue

        vector = tuple(values)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_install = selected

    if best_install is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_install}


def _component_07(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    if k > len(jobs):
        return {"error": "impossible"}
    best_value = None
    best_ids = None
    for chosen in _subsets(jobs, k):
        ids = {job["id"] for job in chosen}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        active = []
        compatible = True
        for job in sorted(chosen, key=lambda item: (item["start"], item["end"])):
            active = [end for end in active if end > job["start"]]
            active.append(job["end"])
            if len(active) > 2:
                compatible = False
                break
        if not compatible:
            continue
        value = sum(job["value"] for job in chosen)
        sorted_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids < best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _subsets(items, k):
    # Generate fixed-size subsets without depending on input ordering.
    if k == 0:
        yield []
        return
    n = len(items)
    indices = list(range(k))
    while True:
        yield [items[i] for i in indices]
        i = k - 1
        while i >= 0 and indices[i] == n - k + i:
            i -= 1
        if i < 0:
            break
        indices[i] += 1
        for j in range(i + 1, k):
            indices[j] = indices[j - 1] + 1


def _component_08(data):
    required = data.get("required", [])
    bit_for = {node: 1 << index for index, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit_for.get(data["source"], 0)
    start_state = (data["source"], initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"],) + start_state]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, remaining - 1))
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival,) + next_state)
    return {"arrival": None}


